customCss:
.wb-addon-portfolio{--pf-accent:#6366f1;--pf-accent-soft:color-mix(in srgb,var(--pf-accent) 14%,transparent);--pf-accent-line:color-mix(in srgb,var(--pf-accent) 40%,transparent);--pf-accent-glow:color-mix(in srgb,var(--pf-accent) 45%,transparent);font-family:inherit;width:100%;box-sizing:border-box;padding:56px 24px;max-width:1200px;margin:0 auto;color:var(--text-main,#f8fafc)}
.wb-addon-portfolio *,.wb-addon-portfolio *::before,.wb-addon-portfolio *::after{box-sizing:border-box}

/* HERO LAYOUT */
.wb-pf-hero{display:grid;grid-template-columns:minmax(220px,300px) 1fr;gap:48px;align-items:center;margin-bottom:72px}
.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-hero{grid-template-columns:1fr minmax(220px,300px)}
.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-photo-wrap{order:2}
.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-intro{order:1;text-align:right}
.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-meta,.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-skills,.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-actions{justify-content:flex-end}

/* SUMMARY ALIGNMENT */
.wb-addon-portfolio[data-pf-summaryalign="left"] .wb-pf-summary{text-align:left}
.wb-addon-portfolio[data-pf-summaryalign="center"] .wb-pf-summary{text-align:center;margin-left:auto;margin-right:auto}
.wb-addon-portfolio[data-pf-summaryalign="right"] .wb-pf-summary{text-align:right;margin-left:auto}
.wb-addon-portfolio[data-pf-summaryalign="justify"] .wb-pf-summary{text-align:justify}

@media(max-width:820px){.wb-pf-hero,.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-hero{grid-template-columns:1fr;gap:32px;text-align:center}.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-photo-wrap{order:0}.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-intro{text-align:center}.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-meta,.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-skills,.wb-addon-portfolio[data-pf-photopos="right"] .wb-pf-actions{justify-content:center}.wb-addon-portfolio .wb-pf-summary{text-align:center;margin-left:auto;margin-right:auto}}

/* PHOTO */
.wb-pf-photo-wrap{position:relative;display:flex;justify-content:center}
.wb-pf-photo{position:relative;width:100%;aspect-ratio:1/1;border-radius:24px;overflow:hidden;background:linear-gradient(135deg,var(--pf-accent),color-mix(in srgb,var(--pf-accent) 40%,#000));box-shadow:0 20px 50px -20px var(--pf-accent-glow),0 0 0 1px rgba(255,255,255,.06) inset;transition:transform .4s ease,box-shadow .4s ease}
.wb-pf-photo::after{content:'';position:absolute;inset:0;border-radius:inherit;background:linear-gradient(180deg,transparent 55%,rgba(0,0,0,.25));pointer-events:none}
.wb-addon-portfolio[data-pf-shape="circle"] .wb-pf-photo{border-radius:50%}
.wb-addon-portfolio[data-pf-shape="square"] .wb-pf-photo{border-radius:4px}
.wb-pf-photo:hover{transform:translateY(-4px) rotate(-.4deg);box-shadow:0 28px 60px -20px var(--pf-accent-glow),0 0 0 1px rgba(255,255,255,.1) inset}
.wb-pf-photo img{width:100%;height:100%;object-fit:cover;display:block}
.wb-pf-photo-initial{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:clamp(3rem,7vw,5rem);font-weight:800;color:#fff;letter-spacing:-.02em;text-shadow:0 4px 20px rgba(0,0,0,.3)}
.wb-pf-photo img[data-failed="1"]{display:none}
.wb-pf-photo img[data-failed="1"] + .wb-pf-photo-initial{display:flex}
.wb-pf-photo-initial{display:none}

/* INTRO */
.wb-pf-intro{min-width:0}
.wb-pf-eyebrow{display:inline-block;padding:5px 12px;border-radius:999px;background:var(--pf-accent-soft);border:1px solid var(--pf-accent-line);color:var(--pf-accent);font-size:.72rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;margin-bottom:16px}
.wb-pf-name{font-size:clamp(2rem,4.5vw,3.2rem);font-weight:800;line-height:1.05;letter-spacing:-.02em;margin:0 0 10px;background:linear-gradient(135deg,var(--text-main,#f8fafc) 40%,var(--pf-accent) 130%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.wb-pf-title{font-size:clamp(1rem,1.6vw,1.2rem);font-weight:600;color:var(--text-muted,#94a3b8);margin:0 0 16px;line-height:1.4}
.wb-pf-meta{display:flex;flex-wrap:wrap;gap:16px;margin-bottom:24px;font-size:.88rem;color:var(--text-muted,#94a3b8)}
.wb-pf-meta-item{display:inline-flex;align-items:center;gap:6px}
.wb-pf-meta-item span:first-child{opacity:.8}
.wb-pf-summary{font-size:1rem;line-height:1.75;color:var(--text-main,#e2e8f0);margin:0 0 28px;max-width:62ch;white-space:pre-wrap;transition:all .2s ease}
.wb-pf-skills{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:28px}
.wb-pf-skill{display:inline-block;padding:6px 13px;border-radius:999px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);color:var(--text-main,#f1f5f9);font-size:.8rem;font-weight:600;transition:all .2s ease}
.wb-pf-skill:hover{background:var(--pf-accent-soft);border-color:var(--pf-accent-line);color:var(--pf-accent);transform:translateY(-1px)}
.wb-pf-actions{display:flex;flex-wrap:wrap;gap:12px}
.wb-pf-btn{display:inline-flex;align-items:center;gap:8px;padding:11px 20px;border-radius:10px;font:inherit;font-size:.9rem;font-weight:700;cursor:pointer;text-decoration:none;transition:all .2s ease;border:1px solid transparent;line-height:1}
.wb-pf-btn--primary{background:var(--pf-accent);color:#fff;box-shadow:0 8px 24px -8px var(--pf-accent-glow)}
.wb-pf-btn--primary:hover{transform:translateY(-2px);box-shadow:0 12px 30px -8px var(--pf-accent-glow);filter:brightness(1.08)}
.wb-pf-btn--ghost{background:transparent;border-color:rgba(255,255,255,.15);color:var(--text-main,#f8fafc)}
.wb-pf-btn--ghost:hover{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.3);transform:translateY(-1px)}

/* PROJECTS */
.wb-pf-projects{margin-top:8px}
.wb-pf-projects-head{display:flex;align-items:center;gap:16px;margin-bottom:28px}
.wb-pf-projects-head h2{font-size:1.4rem;font-weight:800;margin:0;letter-spacing:-.01em;color:var(--text-main,#f8fafc)}
.wb-pf-projects-head::after{content:'';flex:1;height:1px;background:linear-gradient(90deg,rgba(255,255,255,.15),transparent)}
.wb-pf-projects-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
@media(max-width:900px){.wb-pf-projects-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.wb-pf-projects-grid{grid-template-columns:1fr}}
.wb-pf-project{display:flex;flex-direction:column;border-radius:16px;overflow:hidden;background:var(--bg-card,#131b2e);transition:transform .3s ease,box-shadow .3s ease,border-color .3s ease;position:relative}
.wb-addon-portfolio[data-pf-cardstyle="elevated"] .wb-pf-project{box-shadow:0 4px 18px rgba(0,0,0,.25);border:1px solid rgba(255,255,255,.06)}
.wb-addon-portfolio[data-pf-cardstyle="elevated"] .wb-pf-project:hover{transform:translateY(-6px);box-shadow:0 20px 40px -12px var(--pf-accent-glow);border-color:var(--pf-accent-line)}
.wb-addon-portfolio[data-pf-cardstyle="flat"] .wb-pf-project{background:transparent;border:1px solid rgba(255,255,255,.08)}
.wb-addon-portfolio[data-pf-cardstyle="flat"] .wb-pf-project:hover{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.18)}
.wb-addon-portfolio[data-pf-cardstyle="outlined"] .wb-pf-project{background:transparent;border:1.5px solid var(--pf-accent-line)}
.wb-addon-portfolio[data-pf-cardstyle="outlined"] .wb-pf-project:hover{background:var(--pf-accent-soft);border-color:var(--pf-accent)}
.wb-pf-project-cover{aspect-ratio:16/10;overflow:hidden;background:linear-gradient(135deg,var(--pf-accent),color-mix(in srgb,var(--pf-accent) 35%,#000));position:relative;display:flex;align-items:center;justify-content:center;font-size:2.4rem;font-weight:800;color:rgba(255,255,255,.85)}
.wb-pf-project-cover img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s ease}
.wb-pf-project:hover .wb-pf-project-cover img{transform:scale(1.06)}
.wb-pf-project-body{padding:18px 18px 20px;flex:1;display:flex;flex-direction:column}
.wb-pf-project-meta{display:flex;align-items:center;gap:8px;font-size:.72rem;color:var(--text-dim,#94a3b8);margin-bottom:8px;font-weight:600}
.wb-pf-project-meta .dot{width:3px;height:3px;border-radius:50%;background:currentColor;opacity:.6}
.wb-pf-project-title{font-size:1.08rem;font-weight:800;color:var(--text-main,#f8fafc);margin:0 0 8px;line-height:1.3}
.wb-pf-project-desc{font-size:.88rem;line-height:1.6;color:var(--text-muted,#94a3b8);margin:0 0 14px;flex:1}
.wb-pf-project-tags{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:14px}
.wb-pf-project-tag{font-size:.66rem;padding:3px 8px;border-radius:999px;background:var(--pf-accent-soft);border:1px solid var(--pf-accent-line);color:var(--pf-accent);font-weight:700}
.wb-pf-project-link{display:inline-flex;align-items:center;gap:6px;font-size:.84rem;font-weight:700;color:var(--pf-accent);text-decoration:none;transition:gap .2s ease;margin-top:auto}
.wb-pf-project-link:hover{gap:10px}
.wb-pf-empty{padding:48px 20px;text-align:center;color:var(--text-dim,#94a3b8);border:1px dashed rgba(255,255,255,.12);border-radius:12px}

@media(prefers-reduced-motion:reduce){.wb-addon-portfolio *{transition:none!important;animation:none!important}}

customJs:
function onMount(el, props) {
  var root = el.querySelector('.wb-addon-portfolio');
  if (!root) return;

  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };
  var $ = function (sel, ctx) { return (ctx || root).querySelector(sel); };
  var accent = props.accentColor || '#6366f1';
  root.style.setProperty('--pf-accent', accent);

  // -------- PHOTO --------
  var photoMount = $('[data-pf-mount="photo"]');
  if (photoMount) {
    var initial = (props.name || '?').trim().charAt(0).toUpperCase() || '?';
    var src = (props.photoUrl || '').trim();
    var imgHtml = src
      ? '<img src="' + esc(src) + '" alt="' + esc(props.name || 'Portrait') + '" onerror="this.setAttribute(&#39;data-failed&#39;,&#39;1&#39;)">'
      : '';
    photoMount.innerHTML = imgHtml + '<div class="wb-pf-photo-initial">' + esc(initial) + '</div>';
  }

  // -------- META (location / email) --------
  var metaMount = $('[data-pf-mount="meta"]');
  if (metaMount) {
    var meta = [];
    // Inject emojis directly as HTML to bypass the esc() function which causes the '?' boxes on mobile
    if (props.location) {
      meta.push('<span class="wb-pf-meta-item"><span aria-hidden="true">📍</span><span>' + esc(props.location) + '</span></span>');
    }
    if (props.email) {
      meta.push('<span class="wb-pf-meta-item"><span aria-hidden="true">✉️</span><a href="mailto:' + esc(props.email) + '" style="color:inherit;text-decoration:none;border-bottom:1px dashed rgba(255,255,255,.2)">' + esc(props.email) + '</a></span>');
    }
    metaMount.innerHTML = meta.join('');
  }

  // -------- SUMMARY --------
  var sumMount = $('[data-pf-mount="summary"]');
  if (sumMount) sumMount.textContent = props.summary || '';

  // -------- SKILLS --------
  var skillsMount = $('[data-pf-mount="skills"]');
  var showSkills = props.showSkills !== false && props.showSkills !== 'false';
  if (skillsMount) {
    if (!showSkills || !props.skills) {
      skillsMount.style.display = 'none';
    } else {
      var skills = String(props.skills).split(',').map(function (s) { return s.trim(); }).filter(Boolean);
      skillsMount.innerHTML = skills.map(function (s) { return '<span class="wb-pf-skill">' + esc(s) + '</span>'; }).join('');
    }
  }

  // -------- CONTACT ACTIONS --------
  var actMount = $('[data-pf-mount="actions"]');
  var showContact = props.showContactButtons !== false && props.showContactButtons !== 'false';
  if (actMount) {
    if (!showContact) { actMount.style.display = 'none'; }
    else {
      var btns = [];
      if (props.contactBtnLink) btns.push('<a class="wb-pf-btn wb-pf-btn--primary" href="' + esc(props.contactBtnLink) + '">' + esc(props.contactBtnText || 'Get in Touch') + '</a>');
      if (props.workBtnLink) btns.push('<a class="wb-pf-btn wb-pf-btn--ghost" href="' + esc(props.workBtnLink) + '" target="_blank" rel="noopener noreferrer">' + esc(props.workBtnText || 'View Work') + '</a>');
      actMount.innerHTML = btns.join('');
    }
  }

  // -------- PROJECTS --------
  var projMount = $('[data-pf-mount="projects"]');
  var showProjects = props.showProjects !== false && props.showProjects !== 'false';
  var projects = Array.isArray(props.projects) ? props.projects.filter(function (p) { return p && p.title; }) : [];
  if (projMount) {
    if (!showProjects || !projects.length) { projMount.style.display = 'none'; }
    else {
      var label = props.projectsLabel || 'Selected Projects';
      var cards = projects.map(function (p) {
        var cover = p.imageUrl
          ? '<div class="wb-pf-project-cover"><img src="' + esc(p.imageUrl) + '" alt="' + esc(p.title) + '" loading="lazy" onerror="this.style.display=&#39;none&#39;"></div>'
          : '<div class="wb-pf-project-cover">' + esc((p.title || '?').charAt(0).toUpperCase()) + '</div>';
        var tags = String(p.techTags || '').split(',').map(function (t) { return t.trim(); }).filter(Boolean).map(function (t) { return '<span class="wb-pf-project-tag">' + esc(t) + '</span>'; }).join('');
        var metaBits = [];
        if (p.role) metaBits.push(esc(p.role));
        if (p.year) metaBits.push(esc(p.year));
        var metaLine = metaBits.length ? '<div class="wb-pf-project-meta">' + metaBits.join('<span class="dot"></span>') + '</div>' : '';
        var link = p.projectUrl ? '<a class="wb-pf-project-link" href="' + esc(p.projectUrl) + '" target="_blank" rel="noopener noreferrer">View Project <span aria-hidden="true">→</span></a>' : '';
        return '<article class="wb-pf-project">' + cover + '<div class="wb-pf-project-body">' + metaLine + '<h3 class="wb-pf-project-title">' + esc(p.title) + '</h3><p class="wb-pf-project-desc">' + esc(p.description || '') + '</p>' + (tags ? '<div class="wb-pf-project-tags">' + tags + '</div>' : '') + link + '</div></article>';
      }).join('');
      projMount.innerHTML = '<div class="wb-pf-projects-head"><h2>' + esc(label) + '</h2></div><div class="wb-pf-projects-grid">' + cards + '</div>';
    }
  }

  el.__wbDestroy = function () { /* nothing to tear down */ };
}
